const sd = $getWorkflowStaticData('global');
const c = sd.counters || {};
const errors = Array.isArray(sd.error_log) ? sd.error_log : [];
const unitFailures = sd.unit_failures || 0;
const structural = Boolean(sd.structural_error);

const diags = Array.isArray(sd.voc_invalid_diagnostics) ? sd.voc_invalid_diagnostics.slice(0, 20) : [];
const invalidCategoryCounts = diags.reduce((acc, d) => {
  const k = d.category || 'UNKNOWN';
  acc[k] = (acc[k] || 0) + 1;
  return acc;
}, {});

const errCounts = (c.http_429 || 0) + (c.http_503 || 0) + (c.timeouts || 0) + (c.invalid_outputs || 0);

let runStatus = 'success';
if (structural && (c.responses_processed || 0) === 0) runStatus = 'failed';
else if (structural || unitFailures > 0 || errCounts > 0) {
  runStatus = (c.responses_processed || 0) > 0 ? 'partial' : 'failed';
}

const safeErrors = errors.slice(-25).map(e => ({
  node: String(e.node || '').slice(0, 80),
  message: String(e.message || 'error').slice(0, 400),
}));
if ((c.cache_hits || 0) > 0 || (c.review_queue || 0) > 0) {
  safeErrors.push({ node: 'summary', message: `cache_hits=${c.cache_hits || 0}; review_queue=${c.review_queue || 0}` });
}

const runId = sd.run_id || $('Create Run').first().json.run_id;
if (!runId) throw new Error('run_id missing — cannot finish run');

return {
  json: {
    run_id: runId,
    run_status: runStatus,
    responses_found: c.responses_found || 0,
    responses_processed: c.responses_processed || 0,
    gemini_success: c.gemini_success || 0,
    rules_fallback: c.rules_fallback || 0,
    low_confidence: c.low_confidence || 0,
    http_429: c.http_429 || 0,
    http_503: c.http_503 || 0,
    timeouts: c.timeouts || 0,
    invalid_outputs: c.invalid_outputs || 0,
    cache_hits: c.cache_hits || 0,
    review_queue: c.review_queue || 0,
    sanitized_error: safeErrors,
    errors_json: JSON.stringify({ sanitized_errors: safeErrors, invalid_diagnostics: diags, invalid_category_counts: invalidCategoryCounts }),
  },
};
